// A Julia set drawn with spiral lines, wrapped into a Droste spiral: the picture repeats
// inside itself, smaller each time, along a twisting path, so zooming in never ends.
// On the timeline, iFloat0 zooms in, iFloat1 sets the scale from one copy to the next,
// and iFloat2 sets how tightly the spiral lines wind.
#define zoom (1.0 + iFloat0)
#define drosteScale iFloat1
#define spiralRate min(25.0, exp(iFloat2))
#define PI 3.14159265
#define TWO_PI 6.2831853
#define JULIA_C vec2(-0.755, 0.0)
#define MAX_RADIUS 4.16389
#define AA 6.0

// Complex numbers as vec2(real, imaginary).
vec2 cmul(vec2 a, vec2 b) {
  return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

// a raised to the complex power b, using polar form.
vec2 cpow(vec2 a, vec2 b) {
  float r = length(a);
  float th = atan(a.y, a.x);
  return cmul(
    pow(r, b.x) * vec2(cos(th * b.x), sin(th * b.x)),
    exp(-th * b.y) * vec2(cos(b.y * log(r)), sin(b.y * log(r)))
  );
}

// Thin antialiased lines where n is a whole or half number. fwidth gives how fast n
// changes from one pixel to the next, which keeps the lines the same width everywhere.
float lines(float n, float widthScale) {
  return smoothstep(1.5, 0.0, abs(fract(2.0 * n + 0.5) - 0.5) / (fwidth(n) * widthScale));
}

// The picture: spirals drawn on a Julia set. White lines on black.
vec3 image(vec2 uv) {
  // Run the Julia iteration z -> z² + c, which bends the plane into the Julia set's shape.
  vec2 z = 3.75993 * uv;
  for (int i = 0; i < 11; i++) {
    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + JULIA_C;
  }
  float r = length(z);
  float th = atan(z.y, z.x);

  // Two families of spirals winding opposite ways, each drawn over only part of the circle.
  float spiral1 = (spiralRate * r - th) / TWO_PI;
  float spiral2 = (spiralRate * r + atan(z.y, -z.x)) / TWO_PI;
  vec3 col = vec3(1.0 - lines(spiral1, 1.0) * smoothstep(0.0, 0.01, 0.5 * PI - abs(th)));
  col *= col * (1.0 - lines(spiral2, 1.1) * smoothstep(0.0, 0.01, abs(th) - 0.2 * PI));

  // Points that escaped past MAX_RADIUS are outside the Julia set: leave them blank.
  col = mix(vec3(1.0), col, smoothstep(1.5, 0.0, (r - MAX_RADIUS) / 0.01));
  return 1.0 - col;
}

// The Droste effect. A complex power twists the plane so that a scale by drosteScale
// becomes a turn, which joins the copies into one spiral. Points inside the small
// central circle then scale up into the next copy out.
vec2 droste(vec2 uv) {
  uv = cpow(uv, vec2(1.0, log(drosteScale) / TWO_PI));
  for (int i = 0; i < 10 && length(uv) < 0.13636; i++) {
    uv /= drosteScale;
  }
  return uv;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Antialiasing: average a 6 by 6 grid of samples inside the pixel.
  vec3 col = vec3(0.0);
  for (float i = 0.0; i < AA; i += 1.0) {
    for (float j = 0.0; j < AA; j += 1.0) {
      vec2 uv = (fragCoord + vec2(i, j) / AA - 0.5 * iResolution) / iResolution.y;
      // Zoom by powers of drosteScale, so each step in zoom lands on the next copy.
      uv *= pow(drosteScale, zoom);
      col += image(droste(uv));
    }
  }
  fragColor = vec4(col / (AA * AA), 1.0);
}
